const input = $input.first()?.json ?? {};
const truthy = v => v === true || String(v).toLowerCase() === 'true';
const isTest = truthy(input.test_mode) || !input.approval_request_id;
const now = new Date().toISOString();
const suffix = Math.random().toString(36).slice(2, 7).toUpperCase();
const requestId = String(input.approval_request_id || (isTest ? `APR-TEST-${Date.now()}-${suffix}` : ''));
const approvalRequired = truthy(input.approval_required);
const requestType = String(input.approval_type || input.request_type || 'business_action');
const reason = String(input.approval_reason || input.reason || input.message || 'Human authorization required.');
const customerId = String(input.customer_id || 'UNKNOWN');
const correlationId = String(input.correlation_id || '');
const telegramChatId = String(input.telegram_chat_id || '');
const sessionId = String(input.session_id || input.telegram_update_id || '');
const resumeUrl = String(input.resume_url || '').trim();
if (!requestId || requestId.length > 128) throw new Error('Invalid or missing approval_request_id');
if (!isTest && !approvalRequired) throw new Error('Production request must have approval_required=true');
if (!isTest && !resumeUrl) throw new Error('Missing resume_url; refusing to create an approval that cannot resume its originating execution');
// Validate the n8n Cloud Wait-node resume URL.
if (!isTest) {
  const validResumeUrl =
    /^https:\/\/[^/\s]+\/webhook-waiting\/\d+\?signature=[a-fA-F0-9]+$/.test(
      resumeUrl
    );

  if (!validResumeUrl) {
    throw new Error(
      `Invalid n8n resume URL format: ${resumeUrl}`
    );
  }
}
const record = {
  request_id: requestId, customer_id: customerId, telegram_chat_id: telegramChatId,
  session_id: sessionId, request_type: requestType, reason, correlation_id: correlationId,
  ai_recommendation: 'Await human decision; do not execute the requested action yet.',
  status: 'PENDING', created_at: now, reviewer_id: '', reviewer_name: '',
  decision: '', decision_comment: '', decided_at: '',
  test_record: isTest ? 'true' : 'false', resume_url: resumeUrl
};
const safe = v => String(v ?? '').replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const approveAction = isTest ? 'approval_approve_test' : 'approve_support_request';
const rejectAction = isTest ? 'approval_reject_test' : 'reject_support_request';
const blocks = [
 {type:'header',text:{type:'plain_text',text:isTest?'HUMAN APPROVAL — END-TO-END TEST':'HUMAN APPROVAL REQUIRED',emoji:true}},
 {type:'section',text:{type:'mrkdwn',text:`*Request ID:* ${safe(requestId)}\n*Customer:* ${safe(customerId)}\n*Request type:* ${safe(requestType)}\n*Reason:* ${safe(reason)}\n*Status:* PENDING`}},
 {type:'actions',block_id:`approval_${suffix}`,elements:[
  {type:'button',text:{type:'plain_text',text:isTest?'Approve (TEST)':'Approve',emoji:true},style:'primary',action_id:approveAction,value:requestId,confirm:{title:{type:'plain_text',text:'Confirm approval?'},text:{type:'mrkdwn',text:isTest?'Development test only; no business action will run.':'Records authorization only; protected business action remains separately controlled.'},confirm:{type:'plain_text',text:'Approve'},deny:{type:'plain_text',text:'Cancel'}}},
  {type:'button',text:{type:'plain_text',text:isTest?'Reject (TEST)':'Reject',emoji:true},style:'danger',action_id:rejectAction,value:requestId,confirm:{title:{type:'plain_text',text:'Confirm rejection?'},text:{type:'mrkdwn',text:'Rejection must prevent the protected action.'},confirm:{type:'plain_text',text:'Reject'},deny:{type:'plain_text',text:'Cancel'}}}
 ]},
 {type:'context',elements:[{type:'mrkdwn',text:isTest?'Development test approval.':'Decision will be recorded against the originating request.'}]}
];
return [{json:{request_id:requestId,fallback_text:`Approval ${requestId} requires a human decision.`,blocks,approval_record:record,is_test:isTest}}];

const built = $('Code - Build Approval Card and Record').first().json;
const record = built.approval_record ?? {};
return [{json:{
  correlation_id: record.correlation_id || `APR-${record.request_id}`,
  execution_id: String($execution.id),
  workflow_name: "WF_Slack_Approval_Request_Subworkflow_Inputs_v2",
  event_name: "approval_requested",
  status: "PENDING",
  intent: "approval_required",
  target_agent: "approval_required",
  logged_at: new Date().toISOString()
}}];
